class SummaryEvidenceExtractor:
    def extract_character_evidence(
        self,
        character_name: str,
        aliases: list[str],
        chapter_summaries: list[ChapterSummary]
    ) -> list[SummaryEvidence]:
        '''Extract statements about this character from all chapter summaries.'''
        evidence = []
        all_names = [character_name] + aliases

        for summary in chapter_summaries:
            for sentence in self._split_sentences(summary.text):
                if any(name.lower() in sentence.lower() for name in all_names):
                    evidence.append(SummaryEvidence(
                        text=sentence,
                        chapter_index=summary.chapter_index,
                        source='chapter_summary',
                        priority=1  # Higher priority than raw mentions
                    ))
        return evidence

