class TagIdentityExtractor:
    COMPOUND_PATTERN = re.compile(r'([A-Z][a-z]+)/([A-Z][a-z]+)')

    def extract_identity_pairs(self, chapters: list[Chapter]) -> list[tuple[str, str]]:
        '''Find compound tags like 'Cathy/Kate' indicating same person.'''
        pairs = []
        for chapter in chapters:
            for tag in chapter.tags:
                match = self.COMPOUND_PATTERN.search(tag)
                if match:
                    pairs.append((match.group(1), match.group(2)))
        return list(set(pairs))
